  private allowSliding(key: string, t: number): boolean {
    const cutoff = t - this.windowMs
    const stamps = this.slidingTimestamps.get(key) ?? []
    let firstFresh = 0
    while (firstFresh < stamps.length && stamps[firstFresh] <= cutoff) {
